"""v1.8: real API quotes -> explicit budget selections; mobile + laptop/desktop. No mocked fares."""
import os,sys,json,subprocess
from playwright.sync_api import sync_playwright
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)));S=ROOT+'/screenshots'
U=sys.argv[1] if len(sys.argv)>1 else 'http://localhost:8765/'
TAG=sys.argv[2] if len(sys.argv)>2 else 'v18-local'
checks=0;fails=[]
def ok(v,msg):
 global checks
 checks+=1;print(('OK ' if v else 'FAIL ')+msg,flush=True)
 if not v:fails.append(msg)
def snap(p,n,part):p.screenshot(path=f'{S}/{TAG}-{n}-{part}.png')
def airport(p,side,code):
 p.click('#'+('fromOpen' if side=='from' else 'toOpen'));p.fill('#'+side+'AirportSearch',code);p.locator('#'+side+'Airports [data-value="'+code+'"]').click()
def dates(p):
 p.click('#departOpen');p.fill('#depart','2026-11-16');p.fill('#ret','2026-11-22');p.click('#calendarDone')
with sync_playwright() as w:
 b=w.chromium.launch(executable_path='/usr/bin/google-chrome',args=['--no-sandbox'])
 for name,opt in [('iphone',w.devices['iPhone 13']),('pixel',w.devices['Pixel 7']),('laptop',{'viewport':{'width':1366,'height':768}}),('desktop',{'viewport':{'width':1920,'height':1080}})]:
  print('==',name,flush=True);c=b.new_context(**opt,locale='pl-PL',timezone_id='Europe/Warsaw',accept_downloads=True);p=c.new_page();err=[];p.on('pageerror',lambda e:err.append(str(e)));p.goto(U,wait_until='networkidle');ok('v1.8' in p.inner_text('#ver'),'v1.8 footer');ok(p.is_hidden('#tripBudget') and p.is_hidden('#out') and p.is_hidden('#hotelResults') and p.is_hidden('#reportView'),'fresh user: no auto results, selections or report');snap(p,name,'search-panel')
  if name in ['laptop','desktop']:
   ok(p.locator('main').evaluate('(e)=>e.getBoundingClientRect().width')>1100,'desktop uses wide centered container, not phone column');ok(p.locator('#fromOpen').bounding_box()['y']==p.locator('#toOpen').bounding_box()['y'] and p.locator('#toOpen').bounding_box()['x']<p.locator('#departOpen').bounding_box()['x'],'route, dates, passengers and search use a desktop row')
  airport(p,'from','KRK');airport(p,'to','CTA');dates(p);p.click('#go');p.wait_for_function('()=>__planer.ctx?.fl&&!__planer.ctx.fl.loading',timeout=120000);rr=p.evaluate('()=>__planer.ctx.fl.results');ok(len(rr)>2 and p.locator('[data-flight-budget]').count()>=3,'real Ryanair fares have explicit budget checkboxes');ok('wylot + powrót' in p.locator('.flight-budget-choice').first.inner_text(),'round-trip selection explicitly includes outbound and return');p.locator('[data-flight-budget]').nth(0).check();p.locator('[data-flight-budget]').nth(1).check();p.wait_for_function('()=>Math.abs(document.querySelector("#hotelSection").getBoundingClientRect().top)<220',timeout=7000);sf=p.evaluate('BUDGET.snapshot().flight');ok(p.locator('[data-flight-budget]:checked').count()==1 and sf['r']['out']==rr[1]['out'],'flight selection is single, changeable, and highlighted');ok(abs(sf['r']['total']-(sf['r']['priceOut']+sf['r']['priceIn'])*(int(sf['f']['adults'])+int(sf['f']['children'])))<0.02,'selected total sums actual outbound and return fares for all passengers');ok(p.locator('.fl-card.budget-selected').count()==1 and p.locator('#hotelSection').bounding_box()['y']<250,'selecting flight scrolls to hotels without booking');p.wait_for_function('()=>HOTELS.read().place!==null',timeout=20000);hc=p.evaluate('HOTELS.read()');ok(hc['checkin']==sf['r']['outArr'][:10] and hc['checkout']==sf['r']['back'],'hotel follows marked real flight, including alternative dates')
  p.click('#hotelGo');p.wait_for_function('()=>HOTELS.state!==null',timeout=60000);hs=p.evaluate('HOTELS.snapshot()');ok(not hs['failed'] and len(hs['items'])>1,'real Trivago hotel quotes loaded');p.locator('[data-hotel-budget]').first.check();p.wait_for_timeout(350);ok(p.locator('#restOptions').evaluate('(e)=>e.open&&!e.hidden') and p.locator('[data-step="5"]').evaluate('(e)=>e.open'),'marking hotel opens next transport and attractions step');ok(p.locator('#restOptions').evaluate('(e)=>!!(document.querySelector("#hotelSection").compareDocumentPosition(e)&Node.DOCUMENT_POSITION_FOLLOWING)'),'next step is physically below hotels')
  p.locator('[data-hotel-budget]').nth(1).check();ss=p.evaluate('BUDGET.snapshot()');h=ss['hotel'];d=h['item']['deals'][0];ok(p.locator('[data-hotel-budget]:checked').count()==1 and p.locator('.hotel-card.budget-selected').count()==1,'hotel is single-select and highlighted with tick');ok(abs(h['amount']-(d['stay'] if d['stay'] else d['night']*h['nights']))<0.02,'budget uses actual full stay price, not nightly price');ok(abs(ss['total']-sf['r']['total']-h['amount'])<0.02,'sticky summary sums only marked flight and hotel');ok(len(c.pages)==1,'marking does not open a booking or payment page');p.locator('.hotel-card.budget-selected .budget-choice').evaluate('(e)=>e.scrollIntoView({block:"center",behavior:"instant"})');snap(p,name,'hotel-marked-budget')
  if name in ['laptop','desktop']:
   cards=p.locator('.hotel-card');a=cards.nth(0).bounding_box();bb=cards.nth(1).bounding_box();ok(bb['x']>a['x'] and abs(bb['y']-a['y'])<2,'hotel cards in desktop multi-column grid');ok(p.locator('.bar').bounding_box()['width']>1000,'summary bar fits wide desktop');p.locator('#flightsCard').evaluate('(e)=>e.scrollIntoView({block:"start",behavior:"instant"})');snap(p,name,'flights-grid')
  p.locator('#restOptions').scroll_into_view_if_needed();p.fill('[name=budget]','5000');p.fill('[name=budgetTransport]','150');p.fill('[name=budgetFood]','200');p.fill('[name=budgetAttractions]','50');p.fill('[name=budgetOther]','25');ss=p.evaluate('BUDGET.snapshot()');ok(abs(ss['extraTotal']-425)<0.01 and abs(ss['total']-sf['r']['total']-h['amount']-425)<0.02,'optional own planned costs are labelled and included without invented API prices');ok('zostaje' in p.inner_text('.budget-remainder'),'compares sum against budget');p.fill('[name=budget]','1');ok(p.locator('.budget-remainder.over').count()==1 and 'przekroczony' in p.inner_text('.budget-remainder'),'over-budget warning');p.fill('[name=budget]','5000');snap(p,name,'next-step-summary')
  p.click('#genReport');p.wait_for_selector('#reportView:not([hidden])');fr=p.frame_locator('#reportFrame');rt=fr.locator('body').inner_text();total=p.evaluate('FL.zl2(BUDGET.snapshot().total)');ok('Wybrane do budżetu' in rt and h['item']['name'] in rt and total in rt and 'Transport — kwota własna / szacunek' in rt,'report uses selected hotel, selected real flight and total including own planned costs');ok(sf['r']['out'][:4] in rt and 'wybrany do budżetu' in rt and 'Najtańszy znaleziony lot (prawdziwa cena)' not in rt,'timeline and labels refer to marked flight, not cheapest unmarked option');snap(p,name,'selected-report')
  if name=='iphone':
   with p.expect_popup(timeout=40000) as pop:p.click('#pdf2')
   ok(pop.value.url.startswith('blob:'),'iPhone PDF opens for saving or sharing');pop.value.close()
  else:
   with p.expect_download(timeout=40000) as dl:p.click('#pdf2')
   fn=f'{S}/{TAG}-{name}-selected-report.pdf';dl.value.save_as(fn);txt=subprocess.check_output(['pdftotext',fn,'-']).decode();ok('Wybrane do budżetu' in txt and h['item']['name'] in txt and 'kwota własna' in txt and 'Razem' in txt,'downloaded PDF includes marked hotel, flight and planned total with Polish glyphs')
  p.click('#closeReport');pure=p.evaluate('()=>{const h=BUDGET.hotel,d={...h.item.deals[0],stay:null};return BUDGET.stayPrice(d,h.config);}');ok(pure['derived'] and abs(pure['amount']-d['night']*h['nights'])<0.02,'pure fallback helper: real nightly quote × nights, explicitly derived (never injected as an API offer)')
  # Reload must remember the chosen old quote separately, never pretend it is a fresh API search.
  p.reload(wait_until='networkidle');p.wait_for_function('()=>BUDGET.flight&&BUDGET.hotel&&HOTELS.read().place!==null',timeout=20000);rs=p.evaluate('BUDGET.snapshot()');ok(rs['hotel']['item']['id']==h['item']['id'] and abs(rs['total']-ss['total'])<0.02 and rs['restored'],'real selected snapshots and own cost inputs persist');ok(p.is_hidden('#out') and p.is_hidden('#hotelResults') and p.is_hidden('#reportView') and 'Zapisany wybór' in p.inner_text('#tripBudget'),'returning user: stored summary is labelled, not auto results/report');hc=p.evaluate('HOTELS.read()');ok(hc['checkin']==sf['r']['outArr'][:10] and hc['checkout']==sf['r']['back'],'returning hotel fields preserve the marked flight actual dates');p.click('#genReport');p.wait_for_selector('#reportView:not([hidden])');ok('Zapisany wybór' in p.frame_locator('#reportFrame').locator('body').inner_text(),'report after reload discloses saved quoted prices and original timestamp');p.click('#closeReport')
  p.click('#budgetManage');p.click('[data-remove=flight]');ok(p.evaluate('BUDGET.flight===null&&BUDGET.hotel!==null'),'flight can be removed without removing chosen hotel');p.click('#budgetClose');p.click('#genReport');p.wait_for_selector('#reportView:not([hidden])');ok('Lot nie zaznaczono' in p.frame_locator('#reportFrame').locator('body').inner_text(),'unmarked flight is not silently added to hotel-only budget/report');p.click('#closeReport');p.click('#budgetManage');p.click('[data-remove=hotel]');p.click('#budgetClose');ok(p.is_hidden('#tripBudget') and p.evaluate('localStorage.getItem("sowa.planer.budget.v1")===null'),'remove both clears persisted selections and sticky summary')
  if name=='pixel':
   p.locator('.trip-toggle label:has([value=oneway])').click();p.click('#go');p.wait_for_function('()=>__planer.ctx?.fl&&!__planer.ctx.fl.loading',timeout=120000);p.locator('[data-flight-budget]').first.check();ow=p.evaluate('BUDGET.snapshot().flight');ok(ow['r']['back'] is None and abs(ow['r']['total']-ow['r']['priceOut'])<0.02,'one-way checkbox includes outbound only, no invented return');p.click('#genReport');p.wait_for_selector('#reportView:not([hidden])');ok('w jedną stronę' in p.frame_locator('#reportFrame').locator('body').inner_text() and 'Wylot CTA → KRK' not in p.frame_locator('#reportFrame').locator('body').inner_text(),'marked one-way report has no fictional return');p.click('#closeReport')
  ok(not err,'no JavaScript errors '+str(err));ok(p.evaluate('document.documentElement.scrollWidth<=innerWidth'),'no horizontal overflow');c.close()
 b.close()
open(f'{S}/{TAG}-checks.json','w').write(json.dumps({'checks':checks,'fails':fails,'actual_fares_mocked':False},ensure_ascii=False,indent=2));print('CHECKS',checks,'FAIL',len(fails),fails,flush=True);sys.exit(bool(fails))
